WITH benchmark AS (SELECT MAX_BY(pct_change,bizdate) AS value FROM `findsl_ext`.`index_quote` WHERE index_code='000300' AND snapshot_id='akshare-sina-index-2026-07-15-42e29790031f' AND bizdate>=DATE_ADD(DATE_SUB('2026-04-14', INTERVAL '1' MONTH), INTERVAL '1' DAY) AND bizdate<='2026-04-14'), stock_metric AS (SELECT q.mktcode,q.tgtcode,MAX_BY(((q.lastPx-q.preClosePx)*100.0/NULLIF(q.preClosePx,0)),q.bizdate) AS value FROM `newzl`.`hsj_stock_hq_basic` q WHERE q.bizdate>=DATE_ADD(DATE_SUB('2026-04-14', INTERVAL '1' MONTH), INTERVAL '1' DAY) AND q.bizdate<='2026-04-14' GROUP BY q.mktcode,q.tgtcode) SELECT q.mktcode,q.tgtcode,q.bizdate FROM `newzl`.`hsj_stock_hq_basic` q INNER JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=q.mktcode AND t.tgtcode=q.tgtcode AND t.bizdate=q.bizdate INNER JOIN stock_metric s ON s.mktcode=q.mktcode AND s.tgtcode=q.tgtcode CROSS JOIN benchmark b WHERE q.bizdate='2026-04-14' AND s.value>b.value AND q.closePx/10000.0>t.ma60;
